function disable_property(obj::wxPropertyGrid, propName::AbstractString)
    propName_ws = wxString(propName)
    _result = try
        KwxFFI.wxPropertyGrid_DisableProperty(obj.ptr, propName_ws.ptr) != 0
    finally
        Base.delete!(propName_ws)
    end
    return _result
end

